import { ref } from "vue"

// Singleton cache — shared across all component instances
let cachedCategories: { id: number; icon: string; list: string[] }[] | null = null
let loadingPromise: Promise<void> | null = null

const groupLabels: Record<number, string> = {
  0: "😊", 1: "🤝", 3: "🐻", 4: "🍔", 5: "🏠", 6: "⚽", 7: "💡", 8: "❤️", 9: "🚩",
}

async function loadEmojiDataOnce(): Promise<void> {
  if (cachedCategories) return
  if (loadingPromise) return loadingPromise

  loadingPromise = (async () => {
    const raw = (await import("emojibase-data/zh/compact.json")).default as any[]
    const cats = [0, 1, 3, 4, 5, 6, 7, 8, 9].map((g) => ({
      id: g,
      icon: groupLabels[g] || "?",
      list: [] as string[],
    }))
    for (const e of raw) {
      if (e.group === undefined || e.group === 2) continue
      const cat = cats.find((c) => c.id === e.group)
      if (cat && e.unicode) cat.list.push(e.unicode)
    }
    cachedCategories = cats
  })()

  return loadingPromise
}

// Start loading immediately (module level) so data is ready when UI opens
loadEmojiDataOnce()

export function useEmojiPicker() {
  const showEmojiPicker = ref(false)
  const emojiCategories = ref(cachedCategories || [])
  const activeEmojiCat = ref(0)

  async function ensureLoaded() {
    if (emojiCategories.value.length) return
    await loadEmojiDataOnce()
    emojiCategories.value = cachedCategories || []
  }

  return { showEmojiPicker, emojiCategories, activeEmojiCat, ensureLoaded }
}

import { useAuthStore } from "@/stores/auth"

const TOKEN_KEY = "suisui-token"

/** Base URL for API requests. Override via VITE_API_BASE at build time. */
export const API_BASE_URL = (import.meta as Record<string, any>).env?.VITE_API_BASE ?? ""

function getToken(): string {
  try {
    const auth = useAuthStore()
    return auth.getAuthToken()
  } catch (err) {
    console.error("[api] getToken failed, falling back to localStorage:", err)
    return localStorage.getItem(TOKEN_KEY) || ""
  }
}

/**
 * Fetch a URL relative to the API base.
 * Automatically prepends API_BASE_URL and attaches Authorization: Bearer header.
 */
export function apiUrl(path: string): string {
  return API_BASE_URL + path
}

/** Fetch wrapper that automatically attaches Authorization: Bearer header. */
export function authFetch(url: string, options?: RequestInit): Promise<Response> {
  const token = getToken()
  if (token) {
    options = { ...options }
    options.headers = { ...(options.headers as Record<string, string> | undefined), "Authorization": "Bearer " + token }
  }
  return fetch(API_BASE_URL + url, options)
}

/** Shortcut: fetch with JSON body and Authorization header. */
export function authFetchJSON(url: string, data: unknown, method = "POST"): Promise<Response> {
  return authFetch(url, {
    method,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  })
}

﻿import { ref, computed } from "vue"
import { defineStore } from "pinia"

import { authFetch, API_BASE_URL, authFetchJSON } from "@/utils/api"
const AUTH_KEY = "suisui-auth"
const USER_KEY = "suisui-user"
const AVATAR_KEY = "suisui-avatar"
const NICK_KEY = "suisui-nick"
const TOKEN_KEY = "suisui-token"

function clearStorage() {
  ;[AUTH_KEY, USER_KEY, AVATAR_KEY, NICK_KEY, TOKEN_KEY, "suisui-role", "suisui-color"].forEach(k => localStorage.removeItem(k))
}

export const useAuthStore = defineStore("auth", () => {
  const isLoggedIn = ref(false)
  const userName = ref("")
  const userAvatar = ref("")
  const userNickname = ref("")
  const userAppIcon = ref("")
  const userThemeColor = ref("#1976D2")
  const userRole = ref("user")
  const userToken = ref("")
  const isAdmin = computed(() => userRole.value === "admin")
  const ready = ref(false)

  async function init() {
    const storedUser = localStorage.getItem(USER_KEY)
    const storedAuth = localStorage.getItem(AUTH_KEY)
    if (storedAuth === "true" && storedUser) {
      try {
        const token = localStorage.getItem(TOKEN_KEY) || ""
        const res = await fetch(API_BASE_URL + `/api/auth/verify?username=${encodeURIComponent(storedUser)}`, {
          headers: { "Authorization": "Bearer " + token }
        })
        const data = await res.json()
        if (data.valid) {
          isLoggedIn.value = true
          userName.value = storedUser
          userAvatar.value = data.avatar || ""
          userNickname.value = data.nickname || ""
          userRole.value = data.role || "user"
      userThemeColor.value = data.theme_color || "#1976D2"
          localStorage.setItem(AVATAR_KEY, data.avatar || "")
          localStorage.setItem(NICK_KEY, data.nickname || "")
          localStorage.setItem(TOKEN_KEY, token)
          userToken.value = token
          localStorage.setItem("suisui-role", data.role || "user")
          localStorage.setItem("suisui-color", data.theme_color || "#1976D2")
        } else {
          clearStorage()
        }
      } catch (err) {
        console.error("[auth] init token verification failed:", err)
        clearStorage()
        isLoggedIn.value = false
      }
    }
    ready.value = true
  }

  async function updateAvatar(avatar: string) {
    if (!isLoggedIn.value) return
    try {
      await authFetch("/api/auth/avatar", {
        method: "PATCH", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: userName.value, avatar }),
      })
      userAvatar.value = avatar
      localStorage.setItem(AVATAR_KEY, avatar)
    } catch (err) { console.error("[auth] updateAvatar failed:", err) }
  }

  async function updateNickname(nickname: string) {
    if (!isLoggedIn.value) return
    try {
      const res = await authFetch("/api/auth/nickname", {
        method: "PATCH", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: userName.value, nickname }),
      })
      const data = await res.json()
      if (data.success) {
        userNickname.value = data.nickname
        localStorage.setItem(NICK_KEY, data.nickname)
        return null
      }
      return data.error || "修改失败"
    } catch (err) { console.error("[auth] updateNickname failed:", err); return "无法连接服务器" }
  }

  async function updateThemeColor(color: string) {
    if (!isLoggedIn.value) return
    try {
      await authFetch("/api/auth/theme", {
        method: "PATCH", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: userName.value, theme: color }),
      })
      userThemeColor.value = color
    } catch (err) { console.error("[auth] updateThemeColor failed:", err) }
  }

  async function updateAppIcon(appIcon: string) {
    if (!isLoggedIn.value) return
    try {
      await authFetch("/api/auth/app-icon", {
        method: "PATCH", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: userName.value, appIcon }),
      })
      userAppIcon.value = appIcon
    } catch (err) { console.error("[auth] updateAppIcon failed:", err) }
  }

  async function register(username: string, password: string) {
    try {
      const res = await fetch(API_BASE_URL + "/api/auth/register", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      })
      const data = await res.json()
      if (!res.ok) return data.error
      localStorage.setItem(AUTH_KEY, "true")
      localStorage.setItem(USER_KEY, username.trim())
      localStorage.setItem(AVATAR_KEY, ""); localStorage.setItem(NICK_KEY, "")
      localStorage.setItem(TOKEN_KEY, data.token || "")
      localStorage.setItem("suisui-role", data.role || "user")
      localStorage.setItem("suisui-color", "#1976D2")
      isLoggedIn.value = true
      userName.value = username.trim()
      userAvatar.value = ""; userNickname.value = ""; userAppIcon.value = ""; userRole.value = data.role || "user"
      userToken.value = data.token || ""
      userThemeColor.value = "#1976D2"
      return null
    } catch (err) { console.error("[auth] register failed:", err); return "无法连接服务器" }
  }

  async function login(username: string, password: string) {
    try {
      const res = await fetch(API_BASE_URL + "/api/auth/login", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      })
      const data = await res.json()
      if (!res.ok) return data.error
      localStorage.setItem(AUTH_KEY, "true")
      localStorage.setItem(USER_KEY, username.trim())
      localStorage.setItem(AVATAR_KEY, data.avatar || "")
      localStorage.setItem(NICK_KEY, data.nickname || "")
      localStorage.setItem(TOKEN_KEY, data.token || "")
      isLoggedIn.value = true
      userName.value = username.trim()
      userAvatar.value = data.avatar || ""
      userNickname.value = data.nickname || ""
      userToken.value = data.token || ""
      userRole.value = data.role || "user"
      userThemeColor.value = data.theme_color || "#1976D2"
      return null
    } catch (err) { console.error("[auth] login failed:", err); return "无法连接服务器" }
  }

  function logout() {
    clearStorage()
    isLoggedIn.value = false
    userName.value = ""; userAvatar.value = ""; userNickname.value = ""; userAppIcon.value = ""; userThemeColor.value = "#1976D2"; userRole.value = "user"
  }

  function getAuthToken() { return userToken.value || localStorage.getItem(TOKEN_KEY) || "" }

  return { isLoggedIn, userName, userAvatar, userNickname, userAppIcon, userToken, userThemeColor, userRole, isAdmin, ready, getAuthToken,
    init, updateAvatar, updateNickname, updateThemeColor, updateAppIcon, register, login, logout }
})

